# 化石时间线探索台
era = 1   # 1太古代 2古生代 3中生代 4新生代 5现代

hide()
# 时间带（五段彩色横带，越右越近）
i = 0
while i < 5:
    x = -190 + i * 76
    col = "#a3a3a3"
    if i == 1:
        col = "#84cc16"
    if i == 2:
        col = "#f59e0b"
    if i == 3:
        col = "#fbbf24"
    if i == 4:
        col = "#38bdf8"
    if i == era - 1:
        fill_rect(x + 38, 110, 76, 34, col)
    fill_rect(x + 38, 76, 72, 8, col)
    i = i + 1
# 地层剖面（越深越古老）：当前年代的地层高亮
i = 0
while i < 5:
    y = 10 - i * 34
    col = "#d6d3d1"
    if i == 2:
        col = "#fcd34d"
    if i == 0:
        col = "#fda4af"
    if 5 - i == era:
        col = "#f97316"
    fill_rect(0, y, 400, 30, col)
    i = i + 1
emoji = "🦠"
if era == 1:
    emoji = "🦠"
if era == 2:
    emoji = "🐟"
if era == 3:
    emoji = "🦕"
if era == 4:
    emoji = "🦣"
if era == 5:
    emoji = "🧑"
write(emoji, 0, 10 - (5 - era) * 34, "#0f172a", 16)
info = "最原始的生命（蓝藻）"
if era == 2:
    info = "三叶虫繁盛，鱼类登陆"
if era == 3:
    info = "恐龙统治地球"
if era == 4:
    info = "哺乳动物崛起，冰川期"
if era == 5:
    info = "人类文明"
write(info, -110, 150, "#dc2626", 15)
write("带=年代｜地层越深化石越古老", -195, -145, "#64748b", 10)
write("橙=你选的年代对应的地层", -195, -160, "#ea580c", 10)
